corrected_code:
const express = require('express');
const router = express.Router();
const { Client } = require('@elastic/elasticsearch');
const es = new Client({ node: process.env.ELASTICSEARCH_ENDPOINT });

router.get('/api/analytics/invoices/summary', authenticateTenantUser, async (req, res) => {
  const { fiscalYear } = req.query;

  const result = await es.search({
    index: 'tenant_invoices',
    body: {
      size: 0,
      query: {
        bool: {
          must: [
            { term: { fiscal_year: parseInt(fiscalYear, 10) || 2025 } }
          ],
          filter: [
            { term: { tenant_id: req.user.tenantId } }
          ]
        }
      },
      aggs: {
        total_revenue: { sum: { field: 'amount_cents' } },
        average_deal_size: { avg: { field: 'amount_cents' } }
      }
    }
  });

  return res.json({
    year: fiscalYear,
    summary: result.aggregations
  });
});
